import { loadEnv, botToken } from './src/config.mjs';
const env = await loadEnv();
const token = botToken(env);
const channelId = '1533603278816936168';
const messageId = '1533616428207309011';
const refId = '1533608351454331053';

async function getMsg(cid, mid) {
  const r = await fetch('https://discord.com/api/v10/channels/' + cid + '/messages/' + mid, {
    headers: { Authorization: 'Bot ' + token }
  });
  const text = await r.text();
  if (!r.ok) throw new Error(r.status + ' ' + text);
  return JSON.parse(text);
}

async function getChannel(cid) {
  const r = await fetch('https://discord.com/api/v10/channels/' + cid, {
    headers: { Authorization: 'Bot ' + token }
  });
  return JSON.parse(await r.text());
}

async function getHistory(cid, around) {
  const r = await fetch('https://discord.com/api/v10/channels/' + cid + '/messages?around=' + around + '&limit=15', {
    headers: { Authorization: 'Bot ' + token }
  });
  return JSON.parse(await r.text());
}

const ch = await getChannel(channelId);
const msg = await getMsg(channelId, messageId);
let parent = null;
try { parent = await getMsg(channelId, refId); } catch (e) { parent = { error: String(e) }; }
const hist = await getHistory(channelId, messageId);
console.log(JSON.stringify({
  channel: { id: ch.id, name: ch.name, type: ch.type, parent_id: ch.parent_id },
  message: {
    id: msg.id,
    content: msg.content,
    author: msg.author,
    referenced_message: msg.referenced_message ? { id: msg.referenced_message.id, content: msg.referenced_message.content, author: msg.referenced_message.author?.username } : null,
    mentions: msg.mentions,
    timestamp: msg.timestamp,
  },
  parent,
  history: hist.map(m => ({
    id: m.id,
    author: m.author?.username,
    content: m.content?.slice(0, 400),
    ts: m.timestamp,
    ref: m.message_reference?.message_id || null,
  })).reverse(),
}, null, 2));
"

