import { loadEnv } from "../src/config.mjs";

const e = await loadEnv();
const token = e.CLOUDFLARE_API_TOKEN || e.CF_API_TOKEN || "";
const account = "f3372b30093435bacc35b69972abeb2e";
const id = "6cf71128-67e3-47b2-a802-d6c23d6489e0";
const uuid = "aa414996-b849-4241-8108-f9c22a109ae7";

async function q(sql, params = []) {
  const r = await fetch(
    `https://api.cloudflare.com/client/v4/accounts/${account}/d1/database/${id}/query`,
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ sql, params }),
    },
  );
  const j = await r.json();
  return j.result?.[0]?.results || j.errors;
}

console.log(
  "last",
  await q(
    "SELECT MAX(voted_at) AS last_vote, COUNT(*) AS n FROM rootmc_listing_votes WHERE lower(minecraft_uuid)=?",
    [uuid],
  ),
);
console.log(
  "24h",
  await q(
    "SELECT COUNT(*) AS n, MAX(voted_at) AS last_vote FROM rootmc_listing_votes WHERE lower(minecraft_uuid)=? AND voted_at > datetime('now','-1 day')",
    [uuid],
  ),
);
console.log(
  "recent",
  await q(
    "SELECT voted_at, site_id FROM rootmc_listing_votes WHERE lower(minecraft_uuid)=? ORDER BY voted_at DESC LIMIT 8",
    [uuid],
  ),
);

